    }
}

public class Main {
    static int count = 0;

    static synchronized void bump() {
        count = count + 1;
    }

    public static void main(String[] args) throws InterruptedException {
        Thread a = new Thread() {
            public void run() {
                for (int i = 0; i < 1000; i++) {
                    bump();
                }
            }
        };
        Thread b = new Thread() {
            public void run() {
                for (int i = 0; i < 1000; i++) {
                    bump();
                }
            }
        };
        a.start();
        b.start();
        a.join();
        b.join();
        System.out.println(count);
    }
}

